@layer hj.components {
  /* Customise: --hj-status-height */
  .hj-status {
    --_c: var(--hj-fg-dim);
    --_bg: color-mix(in srgb, var(--hj-fg) 7%, transparent);
    display: inline-flex;
    align-items: center;
    gap: calc(6px * var(--hj-density));
    height: var(--hj-status-height, 26px);
    padding: 0 calc(10px * var(--hj-density)) 0 calc(8px * var(--hj-density));
    border-radius: var(--hj-radius-pill);
    background: var(--_bg);
    color: var(--_c);
    font: 600 12.5px / 1 var(--hj-font-sans);
    letter-spacing: -0.005em;
    white-space: nowrap;
    vertical-align: middle;
  }
  .hj-status[data-tone='success'] {
    --_c: var(--hj-success);
    --_bg: var(--hj-success-soft);
  }
  .hj-status[data-tone='warning'] {
    --_c: var(--hj-warning);
    --_bg: var(--hj-warning-soft);
  }
  .hj-status[data-tone='danger'] {
    --_c: var(--hj-danger);
    --_bg: var(--hj-danger-soft);
  }
  .hj-status[data-tone='info'] {
    --_c: var(--hj-info);
    --_bg: var(--hj-info-soft);
  }
  .hj-status[data-tone='pending'] {
    --_c: var(--hj-accent);
    --_bg: var(--hj-accent-soft);
  }
  .hj-status[data-variant='plain'] {
    height: auto;
    padding: 0;
    background: none;
  }

  .hj-status-glyph {
    display: inline-flex;
    font-size: 15px;
    line-height: 0;
  }
  .hj-status-glyph > svg {
    width: 1em;
    height: 1em;
  }
  .hj-status-meta {
    font-weight: 500;
    color: var(--hj-fg-mute);
  }
  .hj-status-meta::before {
    content: '·';
    margin-right: calc(6px * var(--hj-density));
  }

  /* neutral: a still dot · pending: a dot with a ring that breathes outward while work runs */
  .hj-status-dot {
    position: relative;
    width: 7px;
    height: 7px;
    margin: 0 2px;
    border-radius: 50%;
    background: currentColor;
  }
  .hj-status-dot[data-tone='pending']::after {
    content: '';
    position: absolute;
    inset: -3px;
    border-radius: 50%;
    border: 1.5px solid currentColor;
    animation: hj-status-ring 1600ms var(--hj-ease-out) infinite;
    animation-play-state: var(--hj-ambient);
  }
  @keyframes hj-status-ring {
    from {
      transform: scale(0.6);
      opacity: 0.7;
    }
    to {
      transform: scale(1.7);
      opacity: 0;
    }
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import type { IconName } from '../../system/icons.tsx';
import { cls, withDefaults } from '../../system/slot.ts';

export type StatusTone = 'success' | 'warning' | 'danger' | 'info' | 'neutral' | 'pending';

/** Props hanji adds to the status element. */
export interface StatusOwnProps {
  /** What state it names. Each tone has a glyph, so status is never colour alone. */
  tone?: StatusTone;
  /** tint = pill on a soft fill (in lists, tables) · plain = glyph + word only (inline in text). */
  variant?: 'tint' | 'plain';
  /** A muted qualifier after the word — usually when: “2 min ago”, “since 09:14”. */
  meta?: React.ReactNode;
  /** Hide the glyph. Only when the word alone is unmistakable. @default true */
  icon?: boolean;
  render?: useRender.RenderProp;
}

export interface StatusProps
  extends StatusOwnProps, Omit<React.ComponentProps<'span'>, 'className'> {
  className?: string;
}

const GLYPH: Readonly<Record<Exclude<StatusTone, 'pending' | 'neutral'>, IconName>> = {
  success: 'checkCircle',
  warning: 'alert',
  danger: 'xCircle',
  info: 'info',
};

/**
 * A state in words: word + glyph + tint, and when it happened. Pending carries a live ring that
 * pulses while the work runs (and holds still when motion is reduced).
 *
 * @example
 * <Status tone="success" meta="2 min ago">Synced</Status>
 * <Status tone="danger">Couldn’t sync</Status>
 */
export function Status(props: StatusProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    tone = 'neutral',
    variant = 'tint',
    meta,
    icon = true,
    render,
    className,
    children,
    ...rest
  } = withDefaults(config, 'Status', props);
  const styled = !config.unstyled;
  let glyph: React.ReactNode = null;
  if (icon) {
    if (tone === 'pending' || tone === 'neutral') {
      glyph = (
        <span
          className={styled ? 'hj-status-dot' : undefined}
          aria-hidden="true"
          data-tone={tone}
        />
      );
    } else {
      glyph = (
        <span className={styled ? 'hj-status-glyph' : undefined} aria-hidden="true">
          {config.icons[GLYPH[tone]]}
        </span>
      );
    }
  }
  return useRender({
    render,
    defaultTagName: 'span',
    props: {
      ...rest,
      'data-tone': tone,
      'data-variant': variant,
      className: cls(config, 'Status', 'hj-status', className) as string | undefined,
      children: (
        <>
          {glyph}
          <span className={styled ? 'hj-status-word' : undefined}>{children}</span>
          {meta !== undefined && meta !== null ? (
            <span className={styled ? 'hj-status-meta' : undefined}>{meta}</span>
          ) : null}
        </>
      ),
    },
  });
}
